b:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-ordinary-key',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-ordinary-1","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-ordinary-item","product_id":"lab-ordinary-product","product_name":"Synthetic ordinary product","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-ordinary-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}]}'::jsonb);
